select c.id, c.is_in_progress, c.name, c.number_of_learner, c.start_date, c.end_date, c.total_hours, c.total_days, c.daily_hours, c.break_time, c.lesson_start_time, c.lesson_end_time, c.lunch_start_time, c.lunch_end_time from course c


    join learner_enrollment le on c.id = le.course_id where le.user_id = #{id}


    join staff_assignment sa on c.id = sa.course_id where sa.user_id = #{id}



order by c.end_date desc limit 1;

select c.id, c.is_in_progress, c.name, c.number_of_learner, c.start_date, c.end_date, c.total_hours, c.total_days, c.daily_hours, c.break_time, c.lesson_start_time, c.lesson_end_time, c.lunch_start_time, c.lunch_end_time from course c


    join learner_enrollment le on c.id = le.course_id where le.user_id = #{id}


    join staff_assignment sa on c.id = sa.course_id where sa.user_id = #{id}


order by c.end_date desc;
